cd /tmp && cat > /tmp/parity.pl <<'EOF'
my @cases = (
  [],
  ["foo"],
  ["\xff"],
  ["\xff\xfe"],
  ["\x80"],
  ["a\xffb", "\xc3"],
  ["--help"],
  ["\xed\xa0\x80"],
  ("x") x 1,
);
my @bins = ("/workspace/dataset/test1_executable", "/output/test1");
for my $c (@cases) {
  my @res;
  for my $b (@bins) {
    my $o = "/tmp/p_out"; my $e = "/tmp/p_err";
    my $pid = fork();
    if ($pid == 0) {
      open(STDOUT, ">", $o); open(STDERR, ">", $e);
      exec { $b } ($b, @$c) or exit 127;
    }
    waitpid($pid, 0); my $rc = $? >> 8;
    local $/; open(my $fh, "<", $o); my $so = <$fh>; close $fh;
    open($fh, "<", $e); my $se = <$fh>; close $fh;
    push @res, sprintf("rc=%d out=%s err=%dB", $rc, unpack("H*",$so//""), length($se//""));
  }
  my $args = join(",", map { unpack("H*",$_) } @$c);
  printf("args[%s]\n  cpp : %s\n  rust: %s\n  => %s\n", $args, $res[0], $res[1],
    ($res[0] eq $res[1]) ? "IDENTICAL" : "*** DIFFERENT ***");
}
EOF
perl /tmp/parity.pl
